import { fold } from '/Users/eryk.napierala/conductor/workspaces/werk/iqaluit/src/fold.ts'
import { readEvents } from '/Users/eryk.napierala/conductor/workspaces/werk/iqaluit/src/log.ts'
const g: any = fold(readEvents())
const kids = new Map<string, string[]>()
for (const e of g.edges) if (e.type === 'refines') { const a = kids.get(e.to) ?? []; a.push(e.from); kids.set(e.to, a) }
const cards = (id: string): string[] => [id, ...(kids.get(id) ?? []).filter(k => g.nodes.get(k)?.kind === 'card' && !g.nodes.get(k)?.proposed).flatMap(cards)]
const out = []
for (const [id, n] of g.nodes) {
  if (n.kind !== 'card' || n.proposed) continue
  const s = cards(id)
  if (s.length < 3) continue
  const ok = s.every(c => g.nodes.get(c).status === 'decided' && !g.stale.has(c))
  if (!ok) continue
  const paused = s.filter(c => g.paused.has(c)).length
  out.push([s.length, id, paused, n.title])
}
out.sort((a, b) => b[0] - a[0])
for (const o of out) console.log(`${String(o[0]).padStart(3)}  ${o[1].padEnd(34)} paused:${o[2]}  ${o[3]}`)
